function leaveclub_func ( player )	if laGetElementData ( player, "club" ) ~= "none" then		laSetElementData ( player, "club", "none" )		triggerClientEvent ( player, "infobox_start", getRootElement(), "\nDu hast deine\nMitgliedschaft im\nVerein/Club gekündigt.", 7500, 0, 125, 0 )	else		triggerClientEvent ( player, "infobox_start", getRootElement(), "\n\nDu bist in\nkeinem Club/Verein!", 7500, 125, 0, 0 )	endendaddCommandHandler ( "leaveclub", leaveclub_func )